\u6240\u8C13\u7684\u8FA9\u8BC1\uFF0C\u5C31\u662F\u77E5\u6027\u4E0E\u7406\u6027\u7684\u5408\u4E00\u3002

\u4EBA\u4EEC\u5E38\u8BB2\u8FA9\u8BC1\u662F\u201C\u6B63\u53CD\u5408\u201D\uFF0C\u4F46\u4EC0\u4E48\u662F\u6B63\uFF0C\u4EC0\u4E48\u662F\u53CD\uFF0C\u4EC0\u4E48\u662F\u5408\uFF1F

\u6B63\u53CD\u5408\uFF0C\u4EC5\u4EC5\u662F\u4ECE\u5F62\u5F0F\u6837\u8C8C\u4E0A\u8BB2\u51FA\u6765\u7684\u8FA9\u8BC1\u6CD5\u3002\u800C\u5176\u771F\u6B63\u5185\u5BB9\uFF0C\u5374\u5C11\u6709\u4EBA\u77E5\u3002

\u6B63\uFF0C\u6307\u7684\u5C31\u662F\u77E5\u6027\uFF08\u6B63\u601D\uFF09\uFF1B\u53CD\uFF0C\u6307\u7684\u5C31\u662F\u7406\u6027\uFF08\u53CD\u601D\uFF09\uFF1B\u5408\uFF0C\u6307\u7684\u5C31\u662F\u7CBE\u795E\u3002

\u4F46\uFF0C\u552F\u7269\u8FA9\u8BC1\u6CD5\u7684\u6B63\u53CD\u5408\uFF0C\u662F\u975E\u903B\u8F91\u7684\u77DB\u76FE\u7684\uFF1A\u5176\u6B63\u662F\u77E5\u6027\uFF0C\u5176\u53CD\u4E5F\u662F\u77E5\u6027\uFF0C\u5176\u5408\u5219\u662F\u77DB\u76FE\u7684\u77E5\u6027\u3002\uFF08\u4E0D\u4F1A\u53CD\u601D\uFF0C\u4E0D\u61C2\u53CD\u601D\uFF0C\u7F3A\u4E4F\u53CD\u601D\uFF09

\u4E3E\u4F8B\u8BF4\u4E00\u4E0B\u552F\u7269\u8FA9\u8BC1\u6CD5\uFF1A\u5929\u4E0B\u96E8\uFF0C\u6709\u4EBA\u8BF4\u597D\u2014\u2014\u662F\u6B63\uFF0C\u6709\u4EBA\u8BF4\u4E0D\u597D\u2014\u2014\u662F\u53CD\uFF0C\u5176\u5408\u662F\u4E0B\u96E8\u597D\u4E5F\u4E0D\u597D\u2014\u2014\u77DB\u76FE\u3002

\u552F\u7269\u8FA9\u8BC1\u6CD5\u8FD8\u6709\u4E00\u4F8B\uFF1A\u6709\u4EBA\u653E\u5C41\uFF0C\u6709\u4EBA\u8BF4\u81ED\u2014\u2014\u662F\u6B63\uFF0C\u6709\u4EBA\u8BF4\u4E0D\u81ED\u2014\u2014\u662F\u53CD\uFF0C\u5176\u5408\u662F\u653E\u5C41\u65E2\u81ED\u53C8\u4E0D\u81ED\u2014\u2014\u77DB\u76FE\u3002

\u8FD9\u79CD\u8FA9\u8BC1\u6CD5\uFF0C\u5373\u662F\u72D7\u5C41\u7684\u552F\u7269\u8FA9\u8BC1\u6CD5\u3002

\u771F\u6B63\u7684\u8FA9\u8BC1\u6CD5\u662F\uFF0C\u77E5\u6027\u4E0E\u7406\u6027\u7684\u5408\u3002

\u4E3E\u4F8B\u8BB2\uFF1A\u8D28\u2014\u2014\u662F\u4E3B\u89C2\u7684\u89C4\u5B9A\u6027\u7684\u77E5\u6027\uFF1B\u91CF\u2014\u2014\u662F\u5BA2\u89C2\u7684\u5B9E\u5728\u6027\u7684\u7406\u6027\uFF1B\u5EA6\u2014\u2014\u662F\u4E3B\u89C2\u89C4\u5B9A\u6027\u7684\u8D28\u4E0E\u5BA2\u89C2\u5B9E\u5728\u6027\u7684\u91CF\u4E4B\u5408\u3002\u2014\u2014\u8D28\u4E0E\u91CF\u662F\u540C\u4E00\u7684\uFF0C\u4E0D\u662F\u77DB\u76FE\u7684\u3002

\u518D\u4E3E\u4F8B\uFF1A\u4EC1\u662F\u4E3B\u89C2\u89C4\u5B9A\u6027\u7684\u77E5\u6027\uFF1B\u4E49\u662F\u5BA2\u89C2\u5B9E\u9645\u884C\u52A8\u7684\u7406\u6027\uFF1B\u793C\uFF0C\u662F\u4E3B\u89C2\u89C4\u5B9A\u6027\u4EC1\u4E0E\u5BA2\u89C2\u5B9E\u8DF5\u7684\u4E49\u7684\u5408\u2014\u2014\u793C\u6CD5\u5236\u5EA6\uFF08\u884C\u4E3A\u548C\u4E4E\u4EC1\u7684\u89C4\u8303\uFF09\u3002\u2014\u2014\u4EC1\u4E0E\u4E49\u662F\u540C\u4E00\u7684\uFF0C\u4E0D\u662F\u77DB\u76FE\u7684\u3002

\u552F\u7269\u8FA9\u8BC1\u6CD5\uFF0C\u4EC5\u6709\u9ED1\u683C\u5C14\u8FA9\u8BC1\u6CD5\u7684\u5F62\u5F0F\uFF0C\u4F46\u4E0E\u9ED1\u683C\u5C14\u8FA9\u8BC1\u6CD5\u7684\u5185\u6838\u622A\u7136\u76F8\u53CD\u3002

\u6211\u7684\u8FA9\u8BC1\u65B9\u6CD5,\u4ECE\u6839\u672C\u4E0A\u6765\u8BF4,\u4E0D\u4EC5\u548C\u9ED1\u683C\u5C14\u7684\u8FA9\u8BC1\u65B9\u6CD5\u4E0D\u540C,\u800C\u4E14\u548C\u5B83\u622A\u7136\u76F8\u53CD\u3002\u2014\u2014\u300A\u8D44\u672C\u8BBA\u300B
\u9A6C\u514B\u601D\u5199\u300A\u8D44\u672C\u8BBA\u300B\u7684\u65F6\u5019\u8BB2\u4ED6\u7684\u8FA9\u8BC1\u6CD5\u4E0E\u9ED1\u683C\u5C14\u7684\u8FA9\u8BC1\u6CD5\u2014\u2014\u622A\u7136\u76F8\u53CD\u3002\u8FD9\u65F6\uFF0C\u9A6C\u514B\u601D\u5176\u5B9E\u8868\u8FBE\u7684\u610F\u601D\u662F\u2014\u2014\u4E3B\u4F53\u4E0E\u5BA2\u4F53\u7684\u98A0\u5012\u3002\u56E0\u4E3A\uFF0C\u5728\u300A\u8D44\u672C\u8BBA\u300B\u4E2D\u2014\u2014\u4EBA\u5931\u53BB\u4E86\u4E3B\u4F53\u6027\uFF0C\u8D44\u672C\u83B7\u5F97\u4E86\u4E3B\u4F53\u6027\u3002\u4EBA\u662F\u4ECE\u5C5E\u4E8E\u8D44\u672C\u7684\u5974\u96B6\u3002

\u800C\u540E\u6765\u7684\u552F\u7269\u4E3B\u4E49\u8005\uFF0C\u76F4\u63A5\u5C06\u8FD9\u4E2A\u201C\u622A\u7136\u76F8\u53CD\u201D\u89E3\u91CA\u6210\u4E86\u2014\u2014\u77DB\u76FE\uFF0C\u77E5\u6027\u7684\u77DB\u76FE\u3002\u2014\u2014\u65E2\u597D\u53C8\u4E0D\u597D\uFF0C\u65E2\u81ED\u53C8\u4E0D\u81ED\u7684\u8FA9\u8BC1\u6CD5\u3002\u800C\u5931\u53BB\u4E86\u4E3B\u4F53\u6027\u7684\u4EBA\u2014\u2014\u5373\u662F\u552F\u7269\u4E3B\u4E49\u8005\u2014\u2014\u7269\u8D28\uFF08\u8D44\u672C\uFF09\u51B3\u5B9A\u610F\u8BC6\uFF08\u4EBA\uFF09\u2014\u2014\u4E16\u754C\u4E0A\u7684\u4EBA\u90FD\u88AB\u8D44\u672C\u6240\u51B3\u5B9A\u2014\u2014\u6709\u8D44\u672C\u7684\u662F\u8D44\u672C\u5BB6\uFF0C\u65E0\u8D44\u672C\u7684\u662F\u65E0\u4EA7\u8005\u2014\u2014\u603B\u4E4B\uFF0C\u4EBA\u6CA1\u6709\u4E86\u4E3B\u4F53\u6027\u3002
