`.concat(v(["\u6211\u542C\u522B\u4EBA\u8BF4\u8FD9\u4E16\u754C\u4E0A\u6709\u4E00\u79CD\u9E1F\u662F\u6CA1\u6709\u811A\u7684\uFF0C\u5B83\u53EA\u80FD\u4E00\u76F4\u98DE\u5440\u98DE\u5440\uFF0C\u98DE\u7D2F\u4E86\u5C31\u5728\u98CE\u91CC\u9762\u7761\u89C9\uFF0C\u8FD9\u79CD\u9E1F\u4E00\u8F88\u5B50\u53EA\u80FD\u4E0B\u5730\u4E00\u6B21\uFF0C\u90A3\u8FB9\u4E00\u6B21\u5C31\u662F\u5B83\u6B7B\u4EA1\u7684\u65F6\u5019\u3002","\u4EE5\u524D\u6211\u4EE5\u4E3A\u6709\u4E00\u79CD\u9E1F\u4E00\u5F00\u59CB\u5C31\u4F1A\u98DE\uFF0C\u98DE\u5230\u6B7B\u4EA1\u7684\u90A3\u4E00\u5929\u624D\u843D\u5730\u3002\u5176\u5B9E\u5B83\u4EC0\u4E48\u5730\u65B9\u4E5F\u6CA1\u53BB\u8FC7\uFF0C\u90A3\u9E1F\u4E00\u5F00\u59CB\u5C31\u5DF2\u7ECF\u6B7B\u4E86\u3002\u6211\u66FE\u7ECF\u8BF4\u8FC7\u4E0D\u5230\u6700\u540E\u4E00\u523B\u6211\u4E5F\u4E0D\u4F1A\u77E5\u9053\u6700\u559C\u6B22\u7684\u5973\u4EBA\u662F\u8C01\uFF0C\u4E0D\u77E5\u9053\u5979\u73B0\u5728\u5728\u5E72\u4EC0\u4E48\u5462\uFF1F\u5929\u5F00\u59CB\u4EAE\u4E86\uFF0C\u4ECA\u5929\u7684\u5929\u6C14\u770B\u4E0A\u53BB\u4E0D\u9519\uFF0C\u4E0D\u77E5\u9053\u4ECA\u5929\u7684\u65E5\u843D\u4F1A\u662F\u600E\u4E48\u6837\u7684\u5462\uFF1F","\u5341\u516D\u53F7\uFF0C\u56DB\u6708\u5341\u516D\u53F7\u3002\u4E00\u4E5D\u516D\u96F6\u5E74\u56DB\u6708\u5341\u516D\u53F7\u4E0B\u5348\u4E09\u70B9\u4E4B\u524D\u7684\u4E00\u5206\u949F\u4F60\u548C\u6211\u5728\u4E00\u8D77\uFF0C\u56E0\u4E3A\u4F60\u6211\u4F1A\u8BB0\u4F4F\u8FD9\u4E00\u5206\u949F\u3002\u4ECE\u73B0\u5728\u5F00\u59CB\u6211\u4EEC\u5C31\u662F\u4E00\u5206\u949F\u7684\u670B\u53CB\uFF0C\u8FD9\u662F\u4E8B\u5B9E\uFF0C\u4F60\u6539\u53D8\u4E0D\u4E86\uFF0C\u56E0\u4E3A\u5DF2\u7ECF\u8FC7\u53BB\u4E86\u3002\u6211\u660E\u5929\u4F1A\u518D\u6765\u3002","\u6211\u4E0D\u77E5\u9053\u4ED6\u6709\u6CA1\u6709\u56E0\u4E3A\u6211\u800C\u8BB0\u4F4F\u90A3\u4E00\u5206\u949F\uFF0C\u4F46\u6211\u4E00\u76F4\u90FD\u8BB0\u4F4F\u8FD9\u4E2A\u4EBA\u3002\u4E4B\u540E\u4ED6\u771F\u7684\u6BCF\u5929\u90FD\u6765\uFF0C\u6211\u4EEC\u5C31\u4ECE\u4E00\u5206\u949F\u7684\u670B\u53CB\u53D8\u6210\u4E24\u5206\u949F\u7684\u670B\u53CB\uFF0C\u6CA1\u591A\u4E45\uFF0C\u6211\u4EEC\u6BCF\u5929\u81F3\u5C11\u89C1\u4E00\u4E2A\u5C0F\u65F6\u3002","\u6211\u4EE5\u524D\u4EE5\u4E3A\u4E00\u5206\u949F\u5F88\u5FEB\u5C31\u4F1A\u8FC7\u53BB\uFF0C\u5176\u5B9E\u662F\u53EF\u4EE5\u5F88\u957F\u7684\u3002\u6709\u4E00\u5929\u6709\u4E2A\u4EBA\u6307\u7740\u624B\u8868\u8DDF\u6211\u8BF4\uFF0C\u4ED6\u8BF4\u4F1A\u56E0\u4E3A\u90A3\u4E00\u5206\u949F\u800C\u6C38\u8FDC\u8BB0\u4F4F\u6211\uFF0C\u90A3\u65F6\u5019\u6211\u89C9\u5F97\u5F88\u52A8\u542C\u2026\u2026\u4F46\u73B0\u5728\u6211\u770B\u7740\u65F6\u949F\uFF0C\u6211\u5C31\u544A\u8BC9\u81EA\u5DF1\uFF0C\u6211\u8981\u4ECE\u8FD9\u4E00\u5206\u949F\u5F00\u59CB\u5FD8\u6389\u8FD9\u4E2A\u4EBA\u3002","\u4E3A\u4EC0\u4E48\u8981\u8FC1\u5C31\u6211\u5462\uFF1F\u8FC1\u5C31\u5F97\u4E00\u65F6\uFF0C\u8FC1\u5C31\u4E0D\u4E86\u4E00\u8F88\u5B50\uFF0C\u4F60\u548C\u6211\u5728\u4E00\u8D77\u662F\u4E0D\u4F1A\u5FEB\u4E50\u7684\u3002","\u6211\u7EC8\u4E8E\u6765\u5230\u4EB2\u751F\u6BCD\u4EB2\u7684\u5BB6\u4E86\uFF0C\u4F46\u662F\u5979\u4E0D\u80AF\u89C1\u6211\uFF0C\u4F63\u4EBA\u8BF4\u5979\u5DF2\u7ECF\u4E0D\u4F4F\u8FD9\u91CC\u4E86\u3002\u5F53\u6211\u79BB\u5F00\u8FD9\u623F\u5B50\u7684\u65F6\u5019\uFF0C\u6211\u77E5\u9053\u8EAB\u540E\u6709\u4E00\u53CC\u773C\u775B\u76EF\u7740\u6211\uFF0C\u4F46\u6211\u662F\u4E00\u5B9A\u4E0D\u4F1A\u56DE\u5934\u7684\u3002\u6211\u53EA\u4E0D\u8FC7\u60F3\u89C1\u89C1\u5979\uFF0C\u770B\u770B\u5979\u7684\u6837\u5B50\uFF0C\u65E2\u7136\u5979\u4E0D\u7ED9\u6211\u673A\u4F1A\uFF0C\u6211\u4E5F\u4E00\u5B9A\u4E0D\u4F1A\u7ED9\u5979\u673A\u4F1A\u3002","\u6211\u8FD9\u4E00\u751F\u90FD\u4E0D\u77E5\u9053\u8FD8\u4F1A\u559C\u6B22\u591A\u5C11\u4E2A\u5973\u4EBA\uFF0C\u4E0D\u5230\u6700\u540E\u6211\u662F\u4E0D\u77E5\u9053\u54EA\u4E2A\u624D\u662F\u6211\u6700\u559C\u6B22\u7684\u3002","                         ","                         ","                         "]),`


