`.concat(v(["\u5F88\u591A\u5E74\u4E4B\u540E\uFF0C\u6211\u6709\u4E2A\u7EF0\u53F7\u53EB\u505A\u201C\u897F\u6BD2\u201D\u3002\u5176\u5B9E\u4EFB\u4F55\u4EBA\u90FD\u53EF\u4EE5\u53D8\u5F97\u72E0\u6BD2\uFF0C\u53EA\u8981\u4F60\u5C1D\u8BD5\u8FC7\u751A\u4E48\u53EB\u201C\u5FCC\u5992\u201D\u3002\u6211\u4E0D\u4F1A\u4ECB\u610F\u4ED6\u4EBA\u600E\u6837\u770B\u6211\uFF0C\u6211\u53EA\u4E0D\u8FC7\u4E0D\u60F3\u522B\u4EBA\u6BD4\u6211\u66F4\u5F00\u5FC3\u3002","\u770B\u6765\u4F60\u7684\u5E74\u7EAA\u4E5F\u6709\u56DB\u5341\u51FA\u5934\u4E86\uFF0C\u8FD9\u56DB\u5341\u591A\u5E74\u6765\uFF0C\u603B\u6709\u4E9B\u4E8B\u4F60\u662F\u4E0D\u613F\u518D\u63D0\uFF0C\u6216\u662F\u6709\u4E9B\u4EBA\u4F60\u4E0D\u60F3\u518D\u89C1\uFF0C\u6709\u7684\u4EBA\u66FE\u7ECF\u5BF9\u4E0D\u8D77\u4F60\uFF0C\u4E5F\u8BB8\u4F60\u60F3\u8FC7\u8981\u6740\u4E86\u4ED6\u4EEC\uFF0C\u4F46\u662F\u4F60\u4E0D\u6562\u3002\u54C8\uFF0C\u53C8\u6216\u8005\u4F60\u89C9\u5F97\u4E0D\u503C\uFF0C\u5176\u5B9E\u6740\u4EBA\uFF0C\u5F88\u5BB9\u6613\u3002\u6211\u6709\u4E2A\u670B\u53CB\uFF0C\u4ED6\u7684\u6B66\u529F\u975E\u5E38\u597D\uFF0C\u4E0D\u8FC7\u6700\u8FD1\u751F\u6D3B\u6709\u70B9\u56F0\u96BE\uFF0C\u53EA\u8981\u4F60\u968F\u4FBF\u7ED9\u4ED6\u4E00\u70B9\u94F6\u4E24\uFF0C\u4ED6\u4E00\u5B9A\u53EF\u4EE5\u5E2E\u4F60\u6740\u4E86\u90A3\u4E2A\u4EBA\uFF0C\u4F60\u5C3D\u7BA1\u8003\u8651\u4E00\u4E0B\u3002\u5176\u5B9E\u6740\u4E00\u4E2A\u4EBA\u4E0D\u662F\u5F88\u5BB9\u6613\uFF0C\u4E0D\u8FC7\u4E3A\u4E86\u751F\u6D3B\uFF0C\u5F88\u591A\u4EBA\u90FD\u4F1A\u5192\u8FD9\u4E2A\u9669\u3002","\u4E0D\u4E45\u524D\uFF0C\u6211\u9047\u4E0A\u4E00\u4E2A\u4EBA\uFF0C\u9001\u7ED9\u6211\u4E00\u575B\u9152\uFF0C\u5979\u8BF4\u90A3\u53EB\u201C\u9189\u751F\u68A6\u6B7B\u201D\uFF0C\u559D\u4E86\u4E4B\u540E\uFF0C\u53EF\u4EE5\u53EB\u4F60\u5FD8\u6389\u4EE5\u524D\u505A\u8FC7\u7684\u4EFB\u4F55\u4E8B\u3002\u6211\u5F88\u5947\u602A\uFF0C\u4E3A\u4EC0\u4E48\u4F1A\u6709\u8FD9\u6837\u7684\u9152\u3002\u5979\u8BF4\u4EBA\u6700\u5927\u7684\u70E6\u607C\uFF0C\u5C31\u662F\u8BB0\u6027\u592A\u597D\uFF0C\u5982\u679C\u4EC0\u4E48\u90FD\u53EF\u4EE5\u5FD8\u6389\uFF0C\u4EE5\u540E\u7684\u6BCF\u4E00\u5929\u5C06\u4F1A\u662F\u4E00\u4E2A\u65B0\u7684\u5F00\u59CB\uFF0C\u90A3\u4F60\u8BF4\u8FD9\u6709\u591A\u5F00\u5FC3\u3002","\u5176\u5B9E\u201D\u9189\u751F\u68A6\u6B7B\u201C\u53EA\u4E0D\u8FC7\u662F\u5979\u8DDF\u6211\u5F00\u7684\u4E00\u4E2A\u73A9\u7B11\uFF0C\u4F60\u8D8A\u60F3\u77E5\u9053\u81EA\u5DF1\u662F\u4E0D\u662F\u5FD8\u8BB0\u7684\u65F6\u5019\uFF0C\u4F60\u53CD\u800C\u8BB0\u5F97\u6E05\u695A\u3002\u6211\u66FE\u7ECF\u542C\u4EBA\u8BF4\u8FC7\uFF0C\u5F53\u4F60\u4E0D\u80FD\u591F\u518D\u62E5\u6709\uFF0C\u4F60\u552F\u4E00\u53EF\u4EE5\u505A\u7684\uFF0C\u5C31\u662F\u4EE4\u81EA\u5DF1\u4E0D\u8981\u5FD8\u8BB0\u3002","\u4E00\u4E2A\u4EBA\u7684\u8BB0\u6027\u4E0D\u597D\uFF0C\u5C31\u4E0D\u8981\u53BB\u592A\u591A\u662F\u975E\u4E4B\u5730\uFF0C\u56E0\u4E3A\u4F60\u53EF\u80FD\u5FD8\u8BB0\u4F60\u7684\u4EC7\u4EBA\u3002","\u8BA9\u4ED6\u4F24\u5FC3\u53BB\u5427\uFF01\u65E2\u7136\u6211\u8FD9\u4E48\u4E0D\u5F00\u5FC3\uFF0C\u4E3A\u4EC0\u4E48\u4E0D\u627E\u4E00\u4E2A\u4EBA\u966A\u6211\u3002\u6211\u5C31\u662F\u8981\u4ED6\u5C1D\u5C1D\u5F97\u4E0D\u5230\u4E00\u4E2A\u4EBA\u7684\u6ECB\u5473\u3002","\u4F60\u8981\u4E00\u4E2A\u4EBA\u6B7B\uFF0C\u6700\u75DB\u82E6\u7684\u65B9\u6CD5\u5C31\u662F\u5148\u6740\u6389\u4ED6\u6700\u559C\u6B22\u7684\u4EBA\u3002","\u6709\u4E9B\u4EBA\u662F\u79BB\u5F00\u4E4B\u540E\uFF0C\u624D\u4F1A\u53D1\u73B0\u79BB\u5F00\u4E86\u7684\u4EBA\u624D\u662F\u81EA\u5DF1\u7684\u6700\u7231\u3002","\u4E00\u4E2A\u4EBA\u53D7\u5230\u632B\u6298\uFF0C\u6216\u591A\u6216\u5C11\u4F1A\u627E\u4E2A\u501F\u53E3\u63A9\u9970\u81EA\u5DF1\u3002\u5176\u5B9E\u6155\u5BB9\u71D5\u3001\u6155\u5BB9\u5AE3\uFF0C\u53EA\u4E0D\u8FC7\u662F\u540C\u4E00\u4E2A\u4EBA\u7684\u4E24\u4E2A\u8EAB\u4EFD\uFF0C\u5728\u8FD9\u4E24\u4E2A\u8EAB\u4EFD\u540E\u9762\uFF0C\u8EB2\u85CF\u7740\u4E00\u4E2A\u53D7\u4E86\u4F24\u7684\u4EBA\u3002","\u4F60\u77E5\u4E0D\u77E5\u9053\u5417\uFF0C\u6211\u66FE\u7ECF\u627E\u8FC7\u90A3\u4E2A\u5973\u4EBA\uFF0C\u56E0\u4E3A\u6709\u4EBA\u8BF4\u4F60\u6700\u559C\u6B22\u7684\u5973\u4EBA\u662F\u5979\uFF0C\u6211\u672C\u6765\u60F3\u6740\u4E86\u5979\uFF0C\u540E\u6765\u6211\u6CA1\u6709\u8FD9\u6837\u505A\uFF0C\u56E0\u4E3A\u6211\u4E0D\u60F3\u8BC1\u660E\u5979\u5C31\u662F\u3002\u6211\u66FE\u7ECF\u95EE\u8FC7\u81EA\u5DF1\uFF0C\u4F60\u6700\u559C\u6B22\u7684\u5973\u4EBA\u662F\u4E0D\u662F\u6211\uFF0C\u73B0\u5728\u6211\u5DF2\u7ECF\u4E0D\u60F3\u518D\u77E5\u9053\u5566\u3002\u5982\u679C\u6709\u4E00\u5929\u6211\u5FCD\u4E0D\u4F4F\u95EE\u8D77\uFF0C\u4F60\u4E00\u5B9A\u8981\u9A97\u6211\uFF0C\u5C31\u7B97\u4F60\u5FC3\u91CC\u6709\u591A\u4E48\u4E0D\u613F\u610F\uFF0C\u4E5F\u4E0D\u8981\u544A\u8BC9\u6211\u4F60\u6700\u559C\u6B22\u7684\u4EBA\u4E0D\u662F\u6211\u3002","\u5982\u679C\u4F60\u6709\u5FC3\u66FF\u4F60\u5F1F\u5F1F\u62A5\u4EC7\uFF0C\u4F60\u8981\u7B79\u4E00\u7B14\u94B1\uFF0C\u6CA1\u6709\u4EBA\u4F1A\u4E3A\u4E86\u4E00\u53EA\u9A74\u5B50\u53BB\u5F97\u7F6A\u592A\u5C09\u5E9C\u7684\u5200\u5BA2\u3002\u62A5\u4EC7\u662F\u8981\u4ED8\u51FA\u4EE3\u4EF7\u7684\u3002\u8981\u662F\u4F60\u957F\u5F97\u96BE\u770B\uFF0C\u6211\u529D\u4F60\u6B7B\u4E86\u8FD9\u6761\u5FC3\u3002\u4EE5\u4E3A\u6211\u5BF9\u4F60\u6709\u4EC0\u4E48\u4F01\u56FE\uFF0C\u6211\u53EA\u662F\u60F3\u544A\u8BC9\u4F60\uFF0C\u5982\u679C\u8981\u5356\uFF0C\u4F60\u4F1A\u6BD4\u90A3\u9A74\u66F4\u503C\u94B1\u3002","\u6BCF\u4E2A\u4EBA\u90FD\u4F1A\u575A\u6301\u81EA\u5DF1\u7684\u4FE1\u5FF5\uFF0C\u5728\u522B\u4EBA\u6765\u770B\u662F\u6D6A\u8D39\u65F6\u95F4\uFF0C\u5979\u5374\u89C9\u5F97\u5F88\u91CD\u8981\u3002","\u82B1\u4EC0\u4E48\u65F6\u5019\u5F00\u662F\u6709\u5B63\u8282\u7684\uFF0C\u9A6C\u8D3C\u4EC0\u4E48\u65F6\u5019\u5230\u5374\u6CA1\u6709\u4EBA\u77E5\u9053\u3002","\u6211\u4EE5\u524D\u542C\u4EBA\u8BF4\u8FC7\u5982\u679C\u5200\u5FEB\u7684\u8BDD\uFF0C\u8840\u4ECE\u4F24\u53E3\u55B7\u51FA\u6765\u7684\u65F6\u5019\u50CF\u98CE\u58F0\u4E00\u6837\uFF0C\u5F88\u597D\u542C\uFF0C\u60F3\u4E0D\u5230\u7B2C\u4E00\u6B21\u542C\u5230\u7684\u662F\u6211\u81EA\u5DF1\u6D41\u51FA\u6765\u7684\u8840\u3002","\u6709\u4E00\u79CD\u804C\u4E1A\u5F88\u9002\u5408\u4F60\uFF0C\u65E2\u53EF\u4EE5\u5E2E\u4F60\u8D5A\u70B9\u94F6\u4E24\uFF0C\u53C8\u53EF\u4EE5\u884C\u4FA0\u4ED7\u4E49\uFF0C\u4F60\u6709\u5174\u8DA3\u5417\uFF1F\u4F60\u5440\uFF0C\u8003\u8651\u4E00\u4E0B\uFF0C\u4E0D\u8FC7\u8981\u5FEB\u4E00\u70B9\uFF0C\u4F60\u77E5\u9053\uFF0C\u809A\u5B50\u5F88\u5FEB\u4F1A\u997F\u7684\u3002","\u901A\u5E38\u62FF\u4E86\u94B1\u770B\u4E5F\u4E0D\u770B\u7684\u4EBA\uFF0C\u4ED6\u4EEC\u7684\u94B1\u5F88\u5FEB\u5C31\u4F1A\u82B1\u5149\uFF0C\u4F46\u6D2A\u4E03\u6570\u5F97\u5F88\u4ED4\u7EC6\uFF0C\u6211\u77E5\u9053\u8FD9\u79CD\u4EBA\u4E0D\u4F1A\u7559\u5728\u6211\u8EAB\u8FB9\u592A\u4E45\u3002","\u4F60\u4EEC\u89C9\u5F97\u5341\u4E24\u94F6\u5B50\u8FD9\u4E2A\u4EF7\u94B1\u5F88\u8D35\u5417\uFF1F\u90A3\u4F60\u4EEC\u53EF\u4EE5\u627E\u51E0\u4E2A\u4FBF\u5B9C\u70B9\u7684\uFF0C\u90A3\u8FB9\u6709\u51E0\u4E2A\uFF0C\u4E0D\u7A7F\u978B\u7684\u3002\u4F60\u7ED9\u4ED6\u51E0\u4E24\u94F6\u5B50\u4ED6\u5C31\u5F88\u5F00\u5FC3\u3002\u90A3\u4E9B\u8FDE\u978B\u90FD\u6CA1\u6709\u7684\u5200\u5BA2\uFF0C\u4F60\u5BF9\u4ED6\u4EEC\u6709\u4FE1\u5FC3\u5417\uFF1F\u4E07\u4E00\u4ED6\u4EEC\u5931\u624B\u4E86\uFF0C\u8BA9\u90A3\u4E9B\u9A6C\u8D3C\u77E5\u9053\u662F\u7531\u4F60\u4EEC\u6307\u4F7F\u7684\uFF0C\u4F60\u4EEC\u60F3\u90A3\u4E9B\u9A6C\u8D3C\u4F1A\u600E\u4E48\u6837\uFF1F\u6211\u4E0D\u6562\u8BF4\u6211\u8FD9\u4F4D\u670B\u53CB\u7684\u6B66\u529F\u6BD4\u4ED6\u4EEC\u90FD\u597D\uFF0C\u4F46\u662F\u6211\u73B0\u5728\u8DDF\u4F60\u4EEC\u8BF4\u7684\u662F\u4F60\u4EEC\u4E00\u5BB6\u5927\u5C0F\u4E8C\u5341\u51E0\u53E3\u4EBA\u547D\u7684\u5B89\u5168\uFF0C\u81F3\u5C11\u5728\u8FD9\u65B9\u9762\uFF0C\u4F60\u4EEC\u5E94\u8BE5\u76F8\u4FE1\u4E00\u4E2A\u7A7F\u978B\u7684\u4EBA\uFF0C\u662F\u4E0D\u662F\uFF1F","\u522B\u4EE5\u4E3A\u8981\u6B3A\u9A97\u4E00\u4E2A\u5973\u4EBA\u662F\u5F88\u5BB9\u6613\u7684\u4E8B\uFF0C\u8D8A\u662F\u5355\u7EAF\u7684\u5973\u4EBA\u8D8A\u76F4\u63A5\u3002","\u8FD9\u4E2A\u6C99\u6F20\u7684\u540E\u9762\u662F\u4EC0\u4E48\u5730\u65B9\uFF1F    \u662F\u53E6\u5916\u4E00\u4E2A\u6C99\u6F20\u3002","\u6CA1\u4E8B\u7684\u65F6\u5019\u6211\u603B\u662F\u671B\u5411\u767D\u9A7C\u5CF0\uFF0C\u6211\u6E05\u695A\u7684\u8BB0\u5F97\u90A3\u91CC\u6709\u4E2A\u5973\u4EBA\u5728\u7B49\u6211\u3002","\u6BCF\u4E2A\u4EBA\u90FD\u4F1A\u7ECF\u5386\u8FD9\u4E2A\u9636\u6BB5\uFF0C\u770B\u89C1\u4E00\u5EA7\u5C71\uFF0C\u5C31\u60F3\u77E5\u9053\u5C71\u540E\u9762\u662F\u4EC0\u4E48\u3002\u6211\u5F88\u60F3\u544A\u8BC9\u4ED6\uFF0C\u53EF\u80FD\u7FFB\u8FC7\u53BB\u5C71\u540E\u9762\uFF0C\u4F60\u4F1A\u53D1\u89C9\u6CA1\u6709\u4EC0\u4E48\u7279\u522B\uFF0C\u56DE\u5934\u770B\u4F1A\u89C9\u5F97\u8FD9\u8FB9\u66F4\u597D\u3002","\u867D\u7136\u6211\u5F88\u559C\u6B22\u5979\uFF0C\u4F46\u662F\u6211\u4E0D\u60F3\u8BA9\u5979\u77E5\u9053\uFF0C\u56E0\u4E3A\u6211\u660E\u767D\u5F97\u4E0D\u5230\u7684\u4E1C\u897F\u6C38\u8FDC\u662F\u6700\u597D\u7684\u3002\u6BCF\u6B21\u5979\u51DD\u671B\u7740\u90A3\u5C0F\u5B69\u5B50\uFF0C\u6211\u77E5\u9053\u5979\u5FC3\u91CC\u5176\u5B9E\u5728\u60F3\u53E6\u4E00\u4E2A\u4EBA\u3002\u6211\u5F88\u5992\u5FCC\u6B27\u9633\u5CF0\uFF0C\u6211\u5F88\u60F3\u77E5\u9053\u88AB\u4EBA\u559C\u6B22\u7684\u611F\u89C9\u662F\u600E\u6837\u7684\uFF0C\u7ED3\u679C\u6211\u4F24\u5BB3\u4E86\u5F88\u591A\u4EBA\u3002","\u4EE5\u524D\u4E5F\u8FD9\u4E48\u60F3\uFF0C\u4F46\u662F\u770B\u7740\u4ED6\u4E00\u5929\u5929\u957F\u5927\uFF0C\u6211\u77E5\u9053\u4ED6\u65E9\u665A\u4F1A\u79BB\u5F00\u6211\u3002\u73B0\u5728\u6211\u89C9\u5F97\u4EC0\u4E48\u90FD\u65E0\u6240\u8C13\u5566\u3002\u4EE5\u524D\u6211\u8BA4\u4E3A\u90A3\u53E5\u8BDD\u5F88\u91CD\u8981\uFF0C\u56E0\u4E3A\u6211\u89C9\u5F97\u6709\u4E9B\u8BDD\u8BF4\u51FA\u6765\u5C31\u662F\u4E00\u751F\u4E00\u4E16\uFF0C\u73B0\u5728\u60F3\u4E00\u60F3\uFF0C\u8BF4\u4E0D\u8BF4\u4E5F\u6CA1\u6709\u4EC0\u4E48\u5206\u522B\uFF0C\u6709\u4E9B\u4E8B\u4F1A\u53D8\u7684\u3002\u6211\u4E00\u76F4\u4EE5\u4E3A\u662F\u6211\u81EA\u5DF1\u8D62\u4E86\uFF0C\u76F4\u5230\u6709\u4E00\u5929\u770B\u7740\u955C\u5B50\uFF0C\u624D\u77E5\u9053\u81EA\u5DF1\u8F93\u4E86\uFF0C\u5728\u6211\u6700\u7F8E\u597D\u7684\u65F6\u5019\uFF0C\u6211\u6700\u559C\u6B22\u7684\u4EBA\u90FD\u4E0D\u5728\u6211\u8EAB\u8FB9\u3002\u5982\u679C\u80FD\u91CD\u65B0\u5F00\u59CB\u90A3\u8BE5\u591A\u597D\u554A\uFF01","\u6211\u4E00\u76F4\u4EE5\u4E3A\u81EA\u5DF1\u8D62\u4E86\uFF0C\u76F4\u5230\u6709\u4E00\u5929\u770B\u7740\u955C\u5B50\uFF0C\u624D\u77E5\u9053\u81EA\u5DF1\u8F93\u4E86\uFF0C\u5728\u6211\u6700\u7F8E\u597D\u7684\u65F6\u95F4,\u6211\u6700\u559C\u6B22\u7684\u4EBA\u4E5F\u4E0D\u5728\u6211\u8EAB\u8FB9\u3002\u5982\u679C\u65F6\u95F4\u53EF\u4EE5\u91CD\u65B0\u5F00\u59CB\u8BE5\u591A\u597D\u3002","\u6211\u77E5\u9053\u8981\u60F3\u4E0D\u88AB\u4EBA\u62D2\u7EDD\uFF0C\u6700\u597D\u7684\u65B9\u6CD5\u662F\u5148\u62D2\u7EDD\u522B\u4EBA\u3002","\u6700\u4E86\u89E3\u4F60\u7684\u4EBA\u4E0D\u662F\u4F60\u7684\u670B\u53CB\uFF0C\u800C\u662F\u4F60\u7684\u654C\u4EBA\u3002","\u4F60\u77E5\u9053\u559D\u9152\u8DDF\u559D\u6C34\u7684\u5206\u522B\u5417\uFF1F\u9152\uFF0C\u8D8A\u559D\u8D8A\u6696\uFF0C\u6C34\u4F1A\u8D8A\u559D\u8D8A\u5BD2\u3002","                         ","                         ","                         ","                         "]),`

