`.concat(v(["\u53BB2046\u7684\u4E58\u5BA2\u90FD\u53EA\u6709\u4E00\u4E2A\u76EE\u5730\uFF0C\u5C31\u662F\u627E\u56DE\u5931\u53BB\u7684\u8BB0\u5FC6\u3002\u56E0\u4E3A\u57282046\uFF0C\u4E00\u5207\u4E8B\u7269\u6C38\u4E0D\u6539\u53D8\u3002\u6CA1\u6709\u4EBA\u77E5\u9053\u8FD9\u662F\u4E0D\u662F\u771F\u7684\uFF0C\u56E0\u4E3A\u4ECE\u6765\u6CA1\u6709\u4EBA\u56DE\u6765\u8FC7\u3002\u6211\u662F\u552F\u4E00\u7684\u4E00\u4E2A\u3002","\u4E00\u4E2A\u4EBA\u8981\u79BB\u5F002046\uFF0C\u9700\u8981\u591A\u957F\u7684\u65F6\u95F4\uFF1F\u6CA1\u6709\u4EBA\u77E5\u9053\u3002\u6709\u4EBA\u53EF\u4EE5\u6BEB\u4E0D\u8D39\u529B\u5730\u79BB\u5F00\uFF0C\u4F46\u662F\u5BF9\u4E8E\u67D0\u4E9B\u4EBA\u6765\u8BF4\uFF0C\u5374\u9700\u8981\u82B1\u5F88\u957F\u65F6\u95F4\uFF0C\u4ED8\u51FA\u5F88\u591A\u7684\u52AA\u529B\uFF0C\u751A\u81F3\u904D\u4F53\u9CDE\u4F24\u3002\u6211\u5DF2\u60F3\u4E0D\u8D77\u6211\u5728\u8FD9\u5217\u8F66\u4E0A\u5F85\u4E86\u591A\u4E45\uFF0C\u6211\u5F00\u59CB\u6DF1\u6DF1\u5730\u611F\u5230\u5BC2\u5BDE\u3002","\u5728\u4ECE\u524D\uFF0C\u5F53\u4E00\u4E2A\u4EBA\u5FC3\u91CC\u6709\u4E2A\u4E0D\u53EF\u544A\u4EBA\u7684\u79D8\u5BC6\uFF0C\u4ED6\u4F1A\u8DD1\u5230\u6DF1\u5C71\u91CC\uFF0C\u627E\u4E00\u68F5\u6811\uFF0C\u5728\u6811\u4E0A\u6316\u4E2A\u6D1E\uFF0C\u5C06\u79D8\u5BC6\u544A\u8BC9\u90A3\u4E2A\u6D1E\uFF0C\u518D\u7528\u6CE5\u571F\u5C01\u8D77\u6765\uFF0C\u8FD9\u4E2A\u79D8\u5BC6\u5C31\u6C38\u8FDC\u6CA1\u4EBA\u77E5\u9053\u3002","\u6211\u66FE\u7ECF\u7231\u4E0A\u4E00\u4E2A\u4EBA\uFF0C\u540E\u6765\u5979\u8D70\u4E86\u3002\u6211\u53BB2046\uFF0C\u662F\u56E0\u4E3A\u6211\u4EE5\u4E3A\u5979\u5728\u90A3\u91CC\u7B49\u6211\uFF0C\u4F46\u6211\u627E\u4E0D\u5230\u5979\u3002\u6211\u5F88\u60F3\u77E5\u9053\u5979\u5230\u5E95\u559C\u4E0D\u559C\u6B22\u6211\uFF0C\u4F46\u6211\u59CB\u7EC8\u5F97\u4E0D\u5230\u7B54\u6848\u3002\u5979\u7684\u7B54\u6848\u5C31\u50CF\u4E00\u4E2A\u79D8\u5BC6\uFF0C\u6C38\u8FDC\u4E0D\u4F1A\u6709\u4EBA\u77E5\u9053\u3002","\u6211\u66FE\u7ECF\u7231\u4E0A\u4E00\u4E2A\u4EBA\uFF0C\u6211\u60F3\u77E5\u9053\u5979\u5230\u5E95\u559C\u4E0D\u559C\u6B22\u6211\u3002\u6211\u53D1\u73B0\u8FD9\u4E2A\u673A\u5668\u4EBA\u5F88\u50CF\u5979\uFF0C\u6211\u5F00\u59CB\u5C1D\u8BD5\u5728\u5979\u8EAB\u4E0A\u5BFB\u627E\u7B54\u6848\u3002\u6211\u4E0D\u65AD\u7684\u5C1D\u8BD5\uFF0C\u4F46\u5979\u59CB\u7EC8\u6CA1\u6709\u53CD\u5E94\u3002\u5728\u6211\u6700\u5931\u671B\u7684\u65F6\u5019\u6211\u60F3\u8FC7\u653E\u5F03\uFF0C\u53EF\u5F88\u5FEB\u6211\u53C8\u7EE7\u7EED\u3002\u6162\u6162\u7684\u6211\u5F00\u59CB\u6000\u7591\u81EA\u5DF1\uFF0C\u5979\u5BF9\u4F60\u6CA1\u6709\u53CD\u5E94\u672A\u5FC5\u662F\u56E0\u4E3A\u5B83\u53CD\u6620\u8FDF\u949D\uFF0C\u4E5F\u8BB8\u662F\u56E0\u4E3A\u5979\u5BF9\u4F60\u6CA1\u6709\u611F\u89C9\uFF0C\u5230\u6700\u540E\u7EC8\u4E8E\u660E\u767D\uFF0C\u6709\u4E9B\u4E8B\u60C5\u4E0D\u80FD\u52C9\u5F3A\uFF0C\u800C\u6211\u53EF\u4EE5\u505A\u7684\u5C31\u662F\u653E\u5F03\u3002","\u6240\u6709\u7684\u8BB0\u5FC6\u90FD\u662F\u6F6E\u6E7F\u7684\u3002","\u6211\u5F88\u5FEB\u5C31\u9002\u5E94\u4E86\u8FD9\u79CD\u751F\u6D3B\uFF0C\u867D\u7136\u6709\u65F6\u53EA\u662F\u9022\u573A\u4F5C\u620F\uFF0C\u867D\u7136\u6709\u8BB8\u591A\u53EA\u662F\u96FE\u6C34\u60C5\u7F18\uFF0C\u4E0D\u8FC7\u6CA1\u5173\u7CFB\u4E86\uFF0C\u54EA\u6765\u90A3\u4E48\u591A\u4E00\u751F\u4E00\u4E16\u3002","\u5982\u679C\u6709\u4E00\u5929\u4F60\u53EF\u4EE5\u5FD8\u6389\u8FC7\u53BB\uFF0C\u8BB0\u5F97\u6765\u627E\u6211\u3002","\u6709\u4E00\u4E2A\u7B11\u8BDD\uFF0C\u8BF4\u963F\u62C9\u4F2F\u6570\u5B57\u91CC\u76840\u78B0\u89C1\u4E868\uFF0C0\u5C31\u5BF98\u8BF4\uFF0C\u4F60\u4EE5\u4E3A\u7528\u4E00\u6839\u5E26\u5B50\u628A\u8170\u7ED9\u675F\u8D77\u6765\u6211\u5C31\u8BA4\u4E0D\u51FA\u4F60\u4E86\u4E48\uFF1F\u79BB\u5F00\u9999\u6E2F\u51E0\u5E74\uFF0C\u6211\u771F\u89C9\u5F97\u5979\u4ECE0\u53D8\u4F5C\u4E868\uFF01\u4E8E\u662F\uFF0C\u6211\u603B\u6781\u529B\u60F3\u628A8\u4E2D\u95F4\u7684\u90A3\u6839\u8170\u5E26\u89E3\u5F00\u2026\u2026","\u6709\u65F6\u5019\u6211\u89C9\u5F97\u8FD9\u4E2A\u4E16\u754C\u771F\u7684\u53D8\u5F97\u5F88\u6ED1\u7A3D\uFF0C\u4EE5\u524D\u6211\u5199\u5C0F\u8BF4\u662F\u53EA\u60F3\u7ED9\u4E00\u4E2A\u4EBA\u770B\uFF0C\u73B0\u5728\u6211\u5199\u5C0F\u8BF4\u662F\u4E3A\u4E86\u4E0D\u8BA9\u81EA\u5DF1\u6328\u997F\uFF0C\u7ED9\u6240\u6709\u65E0\u804A\u7684\u4EBA\u770B\uFF1B\u4EE5\u524D\u4E24\u4E2A\u6709\u6B32\u671B\u6709\u6FC0\u60C5\u7684\u4EBA\u6781\u529B\u9003\u907F\u5BF9\u65B9\uFF0C\u73B0\u5728\u4E24\u4E2A\u6BEB\u65E0\u6B32\u671B\u6BEB\u65E0\u6FC0\u60C5\u7684\u4EBA\u5374\u6781\u529B\u60F3\u4EB2\u8FD1\u5BF9\u65B9\u2026\u2026\u4E5F\u8BB8\uFF0C\u53EA\u6709\u9152\uFF0C\u624D\u80FD\u91CD\u65B0\u71C3\u70E7\u6211\u7684\u6FC0\u60C5\u3002\u9152\u662F\u597D\u4E1C\u897F\uFF01","\u56E0\u4E3A\u804C\u4E1A\u7684\u9700\u8981\uFF0C\u6211\u5DF2\u7ECF\u4E60\u60EF\u4E86\u7B49\u5F85\u3002\u7136\u800C\uFF0C\u6211\u5374\u4ECE\u6765\u6CA1\u5C1D\u8BD5\u5230\u7B49\u4E00\u4E2A\u4EBA\u7B49\u5F97\u5FC3\u75DB\u7684\u611F\u89C9\uFF01\u4E5F\u4ECE\u6765\u6CA1\u6709\u8BD5\u8FC7\u82B1\u7F8E\u91D1\u4E0D\u662F\u770B\u9762\u989D\u800C\u662F\u7528\u5398\u7C73\u8BA1\u7B97\u7684\u67B6\u52BF\u3002\u5728\u77ED\u77ED\u7684\u4E24\u4E2A\u949F\u5934\u91CC\uFF0C\u4E00\u676F\u5564\u9152\u7684\u4EF7\u94B1\u5DF2\u7ECF\u4ECE\u4E00\u5398\u7C73\u7F8E\u91D1\u6DA8\u5230\u4E86\u4E09\u5398\u7C73\uFF0C\u6211\u5DF2\u7ECF\u559D\u5F97\u591F\u6162\u4E86\uFF0C\u53EF\u6211\u8FD8\u662F\u89C9\u5F97\u81EA\u5DF1\u559D\u5F97\u592A\u5FEB\u4E86\uFF0C\u56E0\u4E3A\u6211\u7684\u670B\u53CB\u8FD8\u6CA1\u51FA\u73B0\uFF0C\u4E0D\u77E5\u9053\u6211\u8FD8\u8981\u7B49\u4ED6\u591A\u4E45\uFF01\u6211\u5F00\u59CB\u5E7B\u60F3\u81EA\u5DF1\u662F\u4E00\u53EA\u5F88\u5C0F\u5F88\u5C0F\u7684\u8682\u8681\uFF0C\u56E0\u4E3A\uFF0C\u4EE5\u5C0F\u8682\u8681\u559D\u9152\u7684\u901F\u5EA6\uFF0C\u4E00\u676F\u5564\u9152\u4E00\u5B9A\u80FD\u559D\u5F88\u4E45\u5F88\u4E45\u2026\u2026","\u6211\u7EC8\u4E8E\u77E5\u9053\u4ED6\u539F\u6765\u662F\u4E00\u4E2A\u90AE\u5DEE\u3002\u800C\u4E14\uFF0C\u6211\u4E5F\u77E5\u9053\u4E86\u6211\u4ECE\u6765\u6CA1\u6709\u5173\u5FC3\u8FC7\u7684\u201C\u4FE1\u201D\u5F88\u5FEB\u5C31\u8981\u5728\u8FD9\u4E2A\u4E16\u754C\u6D88\u5931\u4E86\uFF0C\u5C31\u50CF\u6211\u8BF4\u8FC7\u7684\u90A3\u6837\uFF0C\u4EBA\u4EEC\u603B\u662F\u4F1A\u627E\u5230\u591A\u79CD\u591A\u6837\u7684\u65B9\u6CD5\u8FDB\u884C\u6C9F\u901A\u7684\u3002\u6CA1\u6709\u4E86\u4FE1\uFF0C\u653F\u5E9C\u5C31\u4F1A\u53D6\u6D88\u90AE\u5C40\uFF0C\u8FD9\u4E2A\u4E16\u754C\u4E5F\u5C31\u6CA1\u6709\u4E86\u90AE\u5DEE\uFF0C\u6240\u4EE5\uFF0C\u8FD9\u4E2A\u90AE\u5DEE\u7684\u8EAB\u4EFD\u5C31\u50CF\u6211\u7BB1\u5B50\u91CC\u7684\u7F8E\u91D1\u4E00\u6837\uFF0C\u5F88\u5FEB\u5C31\u8981\u5230\u671F\u4F5C\u5E9F\u4E86\u3002\u4ED6\u544A\u8BC9\u6211\uFF0C\u4ED6\u51C6\u5907\u53BB\u4E00\u4E2A\u5730\u65B9\u78B0\u8FD0\u6C14\uFF0C\u636E\u8BF4\uFF0C\u90A3\u4E2A\u5730\u65B9\u7684\u653F\u7B56\u4F1A\u6301\u7EED\u4E0D\u53D8\u2026\u2026","\u6211\u66FE\u7ECF\u8BD5\u505A\u53E6\u5916\u4E00\u4E2A\u68A6\uFF0C\u7136\u800C\uFF0C\u6211\u5374\u5931\u8D25\u4E86\uFF0C\u6211\u7EC8\u4E8E\u660E\u767D\uFF0C\u6211\u7684\u68A6\u53EA\u5C5E\u4E8E\u90A3\u4E2A\u79BB\u53BB\u7684\u4EBA\uFF01\u6211\u4E5F\u53D1\u73B0\uFF0C\u6709\u68A6\u539F\u6765\u662F\u4E00\u4EF6\u75DB\u82E6\u7684\u4E8B\uFF01","\u90A3\u5929\uFF0C\u4ED6\u95EE\u6211\uFF0C\u5982\u679C\u4ED6\u591A\u4E70\u4E00\u5F20\u7968\uFF0C\u6211\u662F\u4E0D\u662F\u613F\u610F\u8DDF\u4ED6\u8D70\uFF0C\u6211\u62D2\u7EDD\u4E86\u3002\u4E8B\u5B9E\u4E0A\uFF0C\u6211\u662F\u591A\u4E48\u60F3\u8DDF\u4ED6\u4E00\u8D77\u8D70\u554A\uFF0C\u53EF\u4E0D\u77E5\u9053\u4E3A\u4EC0\u4E48\uFF0C\u6211\u8111\u5B50\u91CC\u7684\u82AF\u7247\u5374\u5BF9\u6211\u53D1\u51FA\u4E86\u62D2\u7EDD\u7684\u6307\u4EE4\u2026\u2026","\u5176\u5B9E\u7231\u60C5\u662F\u6709\u65F6\u95F4\u6027\u7684\uFF0C\u8BA4\u8BC6\u5F97\u592A\u65E9\u6216\u592A\u665A\u90FD\u662F\u4E0D\u884C\u7684\uFF0C\u5982\u679C\u6211\u5728\u53E6\u4E00\u4E2A\u65F6\u95F4\u6216\u7A7A\u95F4\u8BA4\u8BC6\u5979\uFF0C\u8FD9\u4E2A\u7ED3\u5C40\u4E5F\u8BB8\u4F1A\u4E0D\u4E00\u6837\u3002","\u7231\u60C5    \u8FD9\u4E1C\u897F\uFF0C\u65F6\u95F4\u5F88\u5173\u952E\uFF0C\u8BA4\u8BC6\u5F97\u592A\u65E9\u6216\u592A\u665A\uFF0C\u90FD\u4E0D\u884C\u3002","\u4ECE\u5979\u8EAB\u4E0A\u6211\u660E\u767D\u4E00\u4E2A\u9053\u7406\uFF0C\u53EA\u8981\u4F60\u81EA\u5DF1\u4E0D\u653E\u5F03\uFF0C\u4F60\u6C38\u8FDC\u90FD\u6709\u673A\u4F1A\u3002","                                  ","                                  ","                                  "]),`

